-- รหัส error ของ REP e-Claim สปสช. ใช้แสดงความหมายและแนวทางแก้ไขใน /fund/uc-debtor
-- ข้อมูลจากเอกสาร สปสช. 31 มี.ค. 2569: C_Validate__20260329_WEB.pdf (รหัสตัวเลข, kind C) และ Deny_20260329_WEB.pdf (A01–D998, kind DENY)
-- แถว DENY คือรหัสรวมที่ REP ใช้บอกว่ามีรหัส Deny รายตัวในคอลัมน์ deny

CREATE TABLE rep_error_code (
  code text PRIMARY KEY,
  kind text NOT NULL CHECK (kind IN ('C', 'DENY')),
  description text,
  fix text,
  source text NOT NULL
);

